31	
32	const RADIAN = Math.PI / 180;
33	
34	interface LabelLayout {
35	    label: ZRText
36	    labelLine: Polyline
37	    position: PieSeriesOption['label']['position']
38	    len: number
39	    len2: number
40	    minTurnAngle: number
41	    maxSurfaceAngle: number
42	    surfaceNormal: Point
43	    linePoints: VectorArray[]
44	    textAlign: HorizontalAlign
45	    labelDistance: number
46	    labelAlignTo: PieSeriesOption['label']['alignTo']
47	    edgeDistance: number
48	    bleedMargin: PieSeriesOption['label']['bleedMargin']
49	    rect: BoundingRect
50	    /**
51	     * user-set style.width.
52	     * This is useful because label.style.width might be changed
53	     * by constrainTextWidth.
54	     */
55	    labelStyleWidth: number
56	    unconstrainedWidth: number
57	    targetTextWidth?: number
58	}
59	
60	function adjustSingleSide(
61	    list: LabelLayout[],
62	    cx: number,
63	    cy: number,
64	    r: number,
65	    dir: -1 | 1,
66	    viewWidth: number,
67	    viewHeight: number,
68	    viewLeft: number,
69	    viewTop: number,
70	    farthestX: number
71	) {
72	    if (list.length < 2) {
73	        return;
74	    }
75	
76	    interface SemiInfo {
77	        list: LabelLayout[]
78	        rB: number
79	        maxY: number
80	    };
81	
82	    function recalculateXOnSemiToAlignOnEllipseCurve(semi: SemiInfo) {
83	        const rB = semi.rB;
84	        const rB2 = rB * rB;
85	        for (let i = 0; i < semi.list.length; i++) {
86	            const item = semi.list[i];
87	            const dy = Math.abs(item.label.y - cy);
88	            // horizontal r is always same with original r because x is not changed.
89	            const rA = r + item.len;
90	            const rA2 = rA * rA;
91	            // Use ellipse implicit function to calculate x
92	            const dx = Math.sqrt(Math.abs((1 - dy * dy / rB2) * rA2));
93	            const newX = cx + (dx + item.len2) * dir;
94	            const deltaX = newX - item.label.x;
95	            const newTargetWidth = item.targetTextWidth - deltaX * dir;
96	            // text x is changed, so need to recalculate width.
97	            constrainTextWidth(item, newTargetWidth, true);
98	            item.label.x = newX;
