import ZRText from 'zrender/src/graphic/Text';
import {
    ensureLabelLayoutWithGeometry,
    newLabelLayoutWithGeometry,
    labelLayoutApplyTranslation,
    labelIntersect,
    LabelLayoutData
} from '@/src/label/labelLayoutHelper';
import { LabelMarginType, LabelExtendedTextStyle } from '@/src/label/labelStyle';

function makeLabel(marginType?: LabelMarginType, margin?: number[]): ZRText {
    const label = new ZRText({
        style: {
            text: 'some label',
            fontSize: 10
        },
        x: 100,
        y: 50
    });
    if (marginType != null) {
        const style = label.style as LabelExtendedTextStyle;
        style.__marginType = marginType;
        style.margin = margin;
    }
    label.update();
    return label;
}

function makeLayout(label: ZRText): LabelLayoutData {
    return {
        label,
        priority: 1,
        defaultAttr: { ignore: false }
    };
}

describe('label-layout-margin', function () {

    it('applies textMargin to the local rect', function () {
        const noMargin = ensureLabelLayoutWithGeometry(makeLayout(makeLabel()));
        const withMargin = ensureLabelLayoutWithGeometry(
            makeLayout(makeLabel(LabelMarginType.textMargin, [2, 4, 6, 8]))
        );
        // [top, right, bottom, left]
        expect(withMargin.rect.x).toBeCloseTo(noMargin.rect.x - 8, 5);
        expect(withMargin.rect.y).toBeCloseTo(noMargin.rect.y - 2, 5);
        expect(withMargin.rect.width).toBeCloseTo(noMargin.rect.width + 8 + 4, 5);
        expect(withMargin.rect.height).toBeCloseTo(noMargin.rect.height + 2 + 6, 5);
    });

    it('applies minMargin to the global rect (style.margin is half of minMargin)', function () {
        const noMargin = ensureLabelLayoutWithGeometry(makeLayout(makeLabel()));
        // minMargin 10 is stored as margin [5, 5, 5, 5] by setTextStyleCommon.
        const withMargin = ensureLabelLayoutWithGeometry(
            makeLayout(makeLabel(LabelMarginType.minMargin, [5, 5, 5, 5]))
        );
        expect(withMargin.rect.x).toBeCloseTo(noMargin.rect.x - 5, 5);
        expect(withMargin.rect.y).toBeCloseTo(noMargin.rect.y - 5, 5);
        expect(withMargin.rect.width).toBeCloseTo(noMargin.rect.width + 10, 5);
        expect(withMargin.rect.height).toBeCloseTo(noMargin.rect.height + 10, 5);
    });

    it('marginForce overrides the user specified margin', function () {
        const label = makeLabel(LabelMarginType.textMargin, [2, 4, 6, 8]);
        const layout = makeLayout(label);
        layout.marginForce = [0, 0, 0, 0];
        const forced = ensureLabelLayoutWithGeometry(layout);
        const noMargin = ensureLabelLayoutWithGeometry(makeLayout(makeLabel()));
        expect(forced.rect.x).toBeCloseTo(noMargin.rect.x, 5);
        expect(forced.rect.y).toBeCloseTo(noMargin.rect.y, 5);
        expect(forced.rect.width).toBeCloseTo(noMargin.rect.width, 5);
        expect(forced.rect.height).toBeCloseTo(noMargin.rect.height, 5);
    });

    it('keeps the computed geometry in sync after post-layout translation', function () {
        const layout = ensureLabelLayoutWithGeometry(
            makeLayout(makeLabel(LabelMarginType.textMargin, [2, 4, 6, 8]))
        );
        const oldX = layout.rect.x;
        const oldY = layout.rect.y;
        labelLayoutApplyTranslation(layout, { x: 15, y: -7 });
        expect(layout.label.x).toBeCloseTo(115, 5);
        expect(layout.label.y).toBeCloseTo(43, 5);
        // The cached global rect must reflect the final post-layout position.
        expect(layout.rect.x).toBeCloseTo(oldX + 15, 5);
        expect(layout.rect.y).toBeCloseTo(oldY - 7, 5);
    });

    it('hideOverlap style intersection uses final geometry and skips ignored labels', function () {
        const layoutA = ensureLabelLayoutWithGeometry(makeLayout(makeLabel()));
        const layoutB = ensureLabelLayoutWithGeometry(makeLayout(makeLabel()));
        // Overlapping initially.
        expect(labelIntersect(layoutA, layoutB)).toBe(true);
        // Move B far away; intersection must be computed from the moved geometry.
        labelLayoutApplyTranslation(layoutB, { x: 1000, y: 0 });
        expect(labelIntersect(layoutA, layoutB)).toBe(false);
        // Ignored labels never intersect.
        labelLayoutApplyTranslation(layoutB, { x: -1000, y: 0 });
        layoutB.label.ignore = true;
        expect(labelIntersect(layoutA, layoutB)).toBe(false);
    });

    it('newLabelLayoutWithGeometry creates an independent variation', function () {
        const source = ensureLabelLayoutWithGeometry(
            makeLayout(makeLabel(LabelMarginType.textMargin, [2, 4, 6, 8]))
        );
        const variant = newLabelLayoutWithGeometry({ marginForce: [0, 0, 0, 0] }, source);
        expect(variant.rect.width).toBeCloseTo(source.rect.width - 12, 5);
        // Source is untouched.
        expect(source.marginForce).toBeUndefined();
    });

});

