import { EChartsType } from '@/src/echarts';
import { createChart } from '../../test/ut/core/utHelper';
import Sector from 'zrender/src/graphic/shape/Sector';
import { Polyline } from '@/src/util/graphic';

describe('labelline_smooth_reset', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function getLabelLineSmooth(): number {
        const seriesModel = chart.getModel().getSeriesByIndex(0);
        const sector = seriesModel.getData().getItemGraphicEl(0) as Sector;
        const labelLine = sector.getTextGuideLine() as Polyline;
        return labelLine.shape.smooth as number;
    }

    function setPie(smooth: boolean | number) {
        chart.setOption({
            series: [{
                type: 'pie',
                radius: ['20%', '50%'],
                label: { show: true },
                labelLine: { show: true, smooth: smooth },
                data: [
                    { value: 40, name: 'a' },
                    { value: 32, name: 'b' },
                    { value: 28, name: 'c' }
                ]
            }]
        });
    }

    it('smooth: true sets a positive smooth factor', function () {
        setPie(true);
        expect(getLabelLineSmooth()).toBeGreaterThan(0);
    });

    it('smooth can be reset to false after being enabled', function () {
        setPie(true);
        expect(getLabelLineSmooth()).toBeGreaterThan(0);
        // Turn smooth off again; the guide line must become straight.
        setPie(false);
        expect(getLabelLineSmooth() > 0).toBe(false);
    });

    it('smooth can be reset to 0 after being enabled', function () {
        setPie(0.5);
        expect(getLabelLineSmooth()).toBeGreaterThan(0);
        setPie(0);
        expect(getLabelLineSmooth() > 0).toBe(false);
    });

});

