import { EChartsType } from '@/src/echarts';
import { createChart } from '../../test/ut/core/utHelper';
import Sector from 'zrender/src/graphic/shape/Sector';

describe('pie_tangential_noflip', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function getLabelRotations(rotate: 'tangential' | 'tangential-noflip'): number[] {
        chart.setOption({
            series: [{
                type: 'pie',
                radius: ['20%', '60%'],
                // slice0: 0 -> 180deg (lower half), slice1: 180 -> 360deg (upper half)
                startAngle: 0,
                label: {
                    show: true,
                    position: 'inside',
                    rotate: rotate
                },
                data: [
                    { value: 1, name: 'bottom' },
                    { value: 1, name: 'top' }
                ]
            }]
        });
        const seriesModel = chart.getModel().getSeriesByIndex(0);
        const rotations: number[] = [];
        seriesModel.getData().each(function (idx) {
            const sector = seriesModel.getData().getItemGraphicEl(idx) as Sector;
            rotations.push(sector.getTextContent().rotation);
        });
        return rotations;
    }

    it('tangential flips labels on the lower half', function () {
        const rotations = getLabelRotations('tangential');
        // bottom slice (midAngle 90deg): flipped to upright (0).
        expect(rotations[0]).toBeCloseTo(0, 5);
        // top slice (midAngle 270deg): no flip needed.
        expect(rotations[1]).toBeCloseTo(0, 5);
    });

    it('tangential-noflip never flips to the opposite reading direction', function () {
        const rotations = getLabelRotations('tangential-noflip');
        // bottom slice: stays on the consistent tangent direction (PI), no flip to 0.
        expect(Math.abs(rotations[0])).toBeCloseTo(Math.PI, 5);
        // top slice: same as tangential.
        expect(rotations[1]).toBeCloseTo(0, 5);
    });

    it('tangential and tangential-noflip differ by PI exactly on the lower half', function () {
        const flipped = getLabelRotations('tangential');
        const noflip = getLabelRotations('tangential-noflip');
        expect(Math.abs(noflip[0] - flipped[0])).toBeCloseTo(Math.PI, 5);
        expect(noflip[1]).toBeCloseTo(flipped[1], 5);
    });

});

